<template>
  <div>
    <StudioHeader><a href="#recent" class="text-button history-shortcut" :aria-label="t('history')"><span class="history-word">{{ t('history') }}</span><span class="history-glyph" aria-hidden="true">↘</span></a></StudioHeader>
    <main class="home-workspace">
      <section class="home-intro"><div><p class="eyebrow">{{ t('eyebrow') }}</p><h1>{{ t('title') }} <em>{{ t('titleEnd') }}</em></h1><p class="intro-copy">{{ t('intro') }}</p></div><svg class="orbital" viewBox="0 0 230 140" fill="none" aria-hidden="true"><ellipse cx="115" cy="70" rx="89" ry="38" transform="rotate(-25 115 70)"/><ellipse cx="115" cy="70" rx="89" ry="38" transform="rotate(25 115 70)"/><ellipse cx="115" cy="70" rx="89" ry="38" transform="rotate(90 115 70)"/><circle cx="115" cy="70" r="6" class="orbit-core"/><circle cx="39" cy="82" r="4" class="orbit-node"/><circle cx="181" cy="35" r="4" class="orbit-node"/><circle cx="127" cy="11" r="3" class="orbit-node"/></svg></section>
      <form class="setup-grid" @submit.prevent="launch">
        <section class="context-card"><p class="section-label">{{ t('context') }}</p><label class="field name-field"><span>{{ t('name') }} <small>· {{ t('optional') }}</small></span><input v-model="name" maxlength="90" :disabled="launching" :placeholder="t('new')" /></label><label class="field question-field"><span>{{ t('question') }}</span><textarea v-model="question" rows="5" minlength="12" maxlength="2400" required :disabled="launching" :placeholder="t('questionHint')" /><small class="character-count mono">{{ question.length }} / 2400</small></label>
          <div class="source-section"><span class="field-label">{{ t('sources') }}</span><div class="source-drop" :class="{dragging}" @dragover.prevent="dragging = true" @dragleave.prevent="dragging = false" @drop.prevent="dropFiles"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 21V6m-6 6 6-6 6 6M7 21v6h18v-6"/></svg><p>{{ t('drop') }}</p><button class="secondary-button" type="button" :disabled="launching" @click="fileInput.click()">+ {{ t('browse') }}</button><small>{{ t('fileHint') }}</small><input ref="fileInput" class="visually-hidden" tabindex="-1" type="file" multiple accept=".pdf,.md,.markdown,.txt" @change="selectFiles" :aria-label="t('browse')" /></div><ul v-if="files.length" class="source-list"><li v-for="(file,index) in files" :key="file.name + file.size"><span class="file-extension">{{ file.name.split('.').pop() }}</span><span>{{ file.name }}<small>{{ (file.size / 1024).toFixed(1) }} KB</small></span><button class="icon-button" type="button" :disabled="launching" @click="files.splice(index,1)" :aria-label="t('remove') + ' ' + file.name">×</button></li></ul><p v-if="fileError" class="error-message" role="alert">{{ fileError }}</p></div>
          <div class="context-caption"><span class="caption-line"></span><p>{{ t('memory') }}</p></div>
        </section>
        <section class="settings-card"><p class="section-label">{{ t('settings') }}</p><fieldset :disabled="launching"><ModelSettings ref="modelSettings" /><div class="round-setting"><div><label for="rounds" class="field-label">{{ t('rounds') }}</label><button type="button" class="pill recommend" @click="rounds = 60">{{ t('recommended') }}</button></div><div class="round-control"><button type="button" @click="rounds = Math.max(1, Number(rounds) - 10)" :disabled="rounds <= 1" :aria-label="t('rounds') + ' −10'">−</button><input id="rounds" v-model.number="rounds" class="mono" type="number" min="1" max="1000" step="1" required /><button type="button" @click="rounds = Math.min(1000, Number(rounds) + 10)" :disabled="rounds >= 1000" :aria-label="t('rounds') + ' +10'">+</button></div><p class="field-hint">{{ t('roundsHint') }}</p></div><label class="field"><span>{{ t('platform') }}</span><select v-model="platform"><option value="parallel">{{ t('both') }}</option><option value="reddit">{{ t('reddit') }}</option><option value="twitter">{{ t('twitter') }}</option></select></label></fieldset><p v-if="error" class="error-message" role="alert">{{ error }}</p><button class="primary-button start-button" type="submit" :disabled="!canLaunch || launching"><span>{{ t(launching ? 'launching' : 'launch') }}</span><span aria-hidden="true">↗</span></button><p class="launch-caption">{{ t('launchHint') }}</p></section>
