<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import StudioHeader from '../studio/StudioHeader.vue'
import ModelSettings from '../studio/ModelSettings.vue'
import { useStudioText } from '../studio/i18n'
import { setPendingUpload } from '../store/pendingUpload'
import { getSimulationHistory } from '../api/simulation'
const { t, locale } = useStudioText(), router = useRouter()
const name = ref(''), question = ref(''), files = ref([]), rounds = ref(60), platform = ref('parallel'), modelSettings = ref(null), fileInput = ref(null), dragging = ref(false), launching = ref(false), error = ref(''), fileError = ref(''), history = ref([]), historyError = ref(false)
const canLaunch = computed(() => question.value.trim().length >= 12 && files.value.length && Number.isInteger(rounds.value) && rounds.value >= 1 && rounds.value <= 1000)
function addFiles(incoming) { if (launching.value) return; fileError.value = ''; for (const file of incoming) { if (!/\.(pdf|md|markdown|txt)$/i.test(file.name) || files.value.reduce((n,f) => n + f.size,0) + file.size > 50 * 1024 * 1024) { fileError.value = t('invalid'); continue } if (!files.value.some(f => f.name === file.name && f.size === file.size)) files.value.push(file) } }
function dropFiles(event) { dragging.value = false; addFiles([...event.dataTransfer.files]) }
function selectFiles(event) { addFiles([...event.target.files]); event.target.value = '' }
async function launch() { if (!canLaunch.value || launching.value) return; launching.value = true; error.value = ''; try { await modelSettings.value.apply(); setPendingUpload(files.value,question.value.trim(),name.value.trim(),{rounds:rounds.value,platform:platform.value}); await router.push('/process/new') } catch(e) { error.value = e.response?.data?.error || e.message; launching.value = false } }
async function loadHistory() { historyError.value = false; try { const res = await getSimulationHistory(8); history.value = Array.isArray(res.data) ? res.data : res.data?.history || res.data?.simulations || [] } catch { historyError.value = true } }
function formatDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '' : date.toLocaleDateString(locale.value,{month:'short',day:'numeric'}) }
onMounted(loadHistory)
</script>
